  const STS={in_visione:["","In visione","bb"],pausata:["","Pausata","bw"],completata:["","Completata","bg"]};
  const OPT={priorita:[["","Nessuna"],["alta","Alta"],["media","Media"],["bassa","Bassa"]],stato_lettura:[["","Non impostato"],["in_lettura","In lettura"],["pausa","In pausa"],["finito","Finito"]],stato_visione:[["","Non impostato"],["in_visione","In visione"],["pausata","Pausata"],["completata","Completata"]]};
  const $=s=>document.querySelector(s);
  const e=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
  const gi=g=>{g=(g||"").toLowerCase();return(GI.find(([k])=>g.includes(k))||[0,""])[1]};
  const fd=d=>d?new Date(d).toLocaleDateString("it-IT"):null;
  const rc=v=>v>=9?"r-gold":v>=8?"r-yellow":v>=6?"r-green":"r-low";
  const rb=v=>v==null?"":`<span class="rt ${rc(v)}">★ ${(+v).toFixed(1)}</span>`;
  const pb=p=>p?`<span class="pl" style="--c:${(PLT[p]||[0,"#64748b"])[1]}">${(PLT[p]||[""])[0]} ${e(p)}</span>`:"";
  function toast(m){const t=$("#toast");t.textContent=m;t.style.pointerEvents="";t.classList.add("show");clearTimeout(toast.h);toast.h=setTimeout(()=>t.classList.remove("show"),2800)}
  function toastUndo(m,fn){const t=$("#toast");t.innerHTML=e(m)+' <button id="undob">Annulla</button>';t.style.pointerEvents="auto";t.classList.add("show");clearTimeout(toast.h);const hide=()=>{t.classList.remove("show");t.style.pointerEvents=""};toast.h=setTimeout(hide,8000);$("#undob").onclick=async()=>{clearTimeout(toast.h);hide();await fn()}}
  const sel=(k,arr,all)=>`<select data-k="${k}"><option value="">${all}</option>${arr.map(v=>`<option${st[k]==v?" selected":""}>${e(v)}</option>`).join("")}</select>`;
  const bars=r=>{const mx=Math.max(1,...r.map(a=>a[1]));return r.map(([l,c])=>`<div class="br"><span>${l}</span><i style="--w:${c/mx*100}%"></i><b>${c}</b></div>`).join("")||"<p>Nessun dato</p>"};
  const sure=(b,l)=>{if(b.dataset.s)return true;b.dataset.s=1;b.textContent="Confermi?";setTimeout(()=>{if(b.isConnected){delete b.dataset.s;b.textContent=l}},3000);return false};
  const pkOpt=(a,all)=>`<option value="">${all}</option>${a.map(v=>`<option>${e(v)}</option>`).join("")}`;
  const fixT=t=>{let s=String(t).replace(/\s{2,}/g," ").trim();TY.forEach(([w,r])=>{s=s.replace(new RegExp("(^|[^\\p{L}])"+w.replace(/[\/\^$*+?.()|[\]{}]/g,"\\$&")+"(?=$|[^\\p{L}])","giu"),(m,p)=>p+r)});return s};
  const normGenre=g=>[...new Set(String(g||"").split(",").map(s=>{const k=s.trim().toLowerCase();return GENRE_NORM[k]||k}).filter(Boolean))].join(", ");
  const nk=t=>fixT(t).toLowerCase().replace(/[^\p{L}\p{N}]/gu,"");
  const acc=(t,b)=>`<details class="ac" open><summary>${t}</summary><div class="acb">${b}</div></details>`;
  const fhm=m=>{const h=Math.floor(m/60),r=Math.round(m%60);return r?`${h}h ${r}m`:`${h}h`};
  const imgIc=(u,f)=>`<img class="cv" src="${e(u)}" alt="" loading="lazy" data-fb="${e(f)}">`;

  document.addEventListener("error",ev=>{const el=ev.target;if(el&&el.tagName=="IMG"&&el.dataset.fb){el.outerHTML=el.dataset.fb}},true);
  let idb=null,D={serie_tv:[],film:[],animazione:[],lego:[],libri:[],progetti:[],note:[]},st={},cur=[],fm={},TASTE={};
  const refreshTaste=()=>{TASTE=tasteMap()};
  const req=r=>new Promise((ok,ko)=>{r.onsuccess=()=>ok(r.result);r.onerror=()=>ko(r.error)});
  const store=(n,m="readonly")=>idb.transaction(n,m).objectStore(n);
  const AUTH={
    usersKey:"mn_users_v1",
    sessKey:"mn_session_v1",
    cur:null,
    getUsers(){try{return JSON.parse(localStorage.getItem(this.usersKey)||"{}")}catch(x){return{}}},
    saveUsers(u){try{localStorage.setItem(this.usersKey,JSON.stringify(u))}catch(x){}},
    getSession(){try{return sessionStorage.getItem(this.sessKey)||localStorage.getItem(this.sessKey)||""}catch(x){return""}},
    setSession(u,remember){try{if(remember)localStorage.setItem(this.sessKey,u);else localStorage.removeItem(this.sessKey);sessionStorage.setItem(this.sessKey,u)}catch(x){}},
    clearSession(){try{localStorage.removeItem(this.sessKey);sessionStorage.removeItem(this.sessKey)}catch(x){}},
    async hash(pw,salt){
      const enc=new TextEncoder().encode(salt+":"+pw);
      if(window.crypto&&crypto.subtle){
        const buf=await crypto.subtle.digest("SHA-256",enc);
        return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,"0")).join("");
      }
      let h=2166136261;for(const b of enc){h^=b;h=Math.imul(h,16777619)}return(h>>>0).toString(16);
    },
    slug(u){return u.trim().toLowerCase().replace(/[^a-z0-9_-]/g,"_")},
    dbName(){return this.cur?"meganavigatore_"+this.slug(this.cur):"meganavigatore"},
    cfgKey(){return this.cur?"mn_cfg_"+this.slug(this.cur):"mn_cfg"},
    async register(username,password,importSeed){
      const u=username.trim(),k=u.toLowerCase();
      if(u.length<3)throw"Il nome utente deve avere almeno 3 caratteri.";
      if(password.length<4)throw"La password deve avere almeno 4 caratteri.";
      const users=this.getUsers();
      if(users[k])throw"Questo nome utente è già registrato.";
      const salt=Math.random().toString(36).slice(2)+Date.now().toString(36);
      const hash=await this.hash(password,salt);
      users[k]={username:u,salt,hash,created:Date.now(),seeded:!importSeed};
      this.saveUsers(users);
      this.cur=u;
      this.setSession(u,true);
      return users[k];
    },
    async login(username,password,remember){
      const u=username.trim(),k=u.toLowerCase();
      const users=this.getUsers(),rec=users[k];
      if(!rec)throw"Nome utente non trovato.";
      const hash=await this.hash(password,rec.salt);
      if(hash!==rec.hash)throw"Password errata.";
      this.cur=rec.username;
      this.setSession(rec.username,remember);
      return rec;
    },
    async changePassword(oldPw,newPw){
      if(newPw.length<4)throw"La nuova password deve avere almeno 4 caratteri.";
      const users=this.getUsers(),rec=users[this.cur.toLowerCase()];
      if(!rec)throw"Account non trovato.";
      if(await this.hash(oldPw,rec.salt)!==rec.hash)throw"La password attuale non è corretta.";
      rec.salt=Math.random().toString(36).slice(2)+Date.now().toString(36);
      rec.hash=await this.hash(newPw,rec.salt);
      this.saveUsers(users);
    },
    async deleteAccount(username, password){
      const k=username.trim().toLowerCase();
      const users=this.getUsers(),rec=users[k];
      if(!rec)throw"Account non trovato.";
      if(await this.hash(password,rec.salt)!==rec.hash)throw"Password errata: impossibile eliminare l'account.";
      const dbN="meganavigatore_"+this.slug(rec.username);
      const cfgK="mn_cfg_"+this.slug(rec.username);
      const seedK="mn_seed_"+this.slug(rec.username);
      if(this.cur&&this.cur.toLowerCase()===k&&idb){try{idb.close()}catch(x){}idb=null}
      await new Promise(res=>{try{const reqDel=indexedDB.deleteDatabase(dbN);reqDel.onsuccess=res;reqDel.onerror=res;reqDel.onblocked=res}catch(x){res()}});
      try{localStorage.removeItem(cfgK);localStorage.removeItem(seedK)}catch(x){}
      delete users[k];
      this.saveUsers(users);
      if(this.cur&&this.cur.toLowerCase()===k){
        this.clearSession();
        this.cur=null;
        D={serie_tv:[],film:[],animazione:[],lego:[],libri:[],progetti:[],note:[]};
        showAuthGate("login");
      }
    },
    exportFullProfile(){
      const users=this.getUsers();
      const rec=users[this.cur.toLowerCase()]||null;
      const tmdb=localStorage.getItem("mn_tmdb")||"";
      const rb=localStorage.getItem("mn_rb")||"";
      return{
        app:"meganavigatore_profile",
        app_versione:APP_VERSION,
        versione:VER,
        esportato:new Date().toISOString(),
        account:rec,
        impostazioni:getCfg(),
        chiavi_api:{tmdb,rb},
        tabelle:{serie_tv:D.serie_tv,film:D.film,animazione:D.animazione,lego:D.lego,libri:D.libri,progetti:D.progetti,note:D.note}
      };
    },
    logout(){
      this.clearSession();
      this.cur=null;
      if(idb){try{idb.close()}catch(x){}idb=null}
      D={serie_tv:[],film:[],animazione:[],lego:[],libri:[],progetti:[],note:[]};
      showAuthGate("login");
    }
  };
  async function openDB(){
    if(idb){try{idb.close()}catch(x){}idb=null}
    try{
      const dbN=AUTH.dbName();
      const need=[...names,...EXTRA,"meta"],op=v=>new Promise((ok,ko)=>{
        const o=v?indexedDB.open(dbN,v):indexedDB.open(dbN);
        o.onupgradeneeded=()=>need.forEach(n=>{if(!o.result.objectStoreNames.contains(n))o.result.createObjectStore(n,{keyPath:"id",autoIncrement:true})});
        o.onsuccess=()=>{o.result.onversionchange=()=>o.result.close();ok(o.result)};
        o.onerror=()=>ko(o.error);o.onblocked=()=>ko("blocked")
      });
      let d=await op();
      if(!need.every(n=>d.objectStoreNames.contains(n))){const v=d.version+1;d.close();d=await op(v)}
      idb=d;
    }catch(x){idb=null}
  }
  function showAuthGate(mode="login"){
    const gate=$("#auth-gate");
    const users=Object.values(AUTH.getUsers());
    if(!users.length)mode="register";
    const isReg=mode==="register";
    gate.innerHTML=`<div class="auth-box">
      <div style="text-align:center">
        <div class="logo" style="font-size:1.6rem;cursor:default">MyMultyScreen</div>
        <p style="margin:6px 0 0;color:var(--mut);font-size:.9rem">${isReg?"Crea il tuo account personale":"Accedi al tuo catalogo"}</p>
      </div>
      <div class="auth-tabs">
        <button type="button" id="tab-login" class="${!isReg?"on":""}">Accedi</button>
        <button type="button" id="tab-reg" class="${isReg?"on":""}">Registrati</button>
      </div>
      <form id="auth-form" autocomplete="on">
        <label>Nome utente
          <input id="au-user" type="text" required minlength="3" autocomplete="username" placeholder="Es. NerdMaster" value="${!isReg&&users.length===1?e(users[0].username):""}">
        </label>
        <label>Password
          <input id="au-pass" type="password" required minlength="4" autocomplete="${isReg?"new-password":"current-password"}" placeholder="••••••••">
        </label>
        ${isReg?`<label>Conferma password
          <input id="au-pass2" type="password" required minlength="4" autocomplete="new-password" placeholder="••••••••">
        </label>
        <label class="cb" style="margin-top:10px;font-weight:400">
          <input id="au-seed" type="checkbox" checked> Carica il catalogo iniziale di esempio
        </label>`:`<label class="cb" style="margin-top:10px;font-weight:400">
          <input id="au-rem" type="checkbox" checked> Resta connesso su questo dispositivo
        </label>`}
        <div class="auth-err" id="au-err"></div>
        <button type="submit" class="pri" style="width:100%;margin-top:12px;padding:11px">${isReg?"Crea account ed entra":"Entra nella Base"}</button>
      </form>
      <div style="margin-top:14px;padding-top:12px;border-top:1px solid var(--line);text-align:center">
        <button type="button" id="au-imp-prof" style="width:100%">Importa profilo completo (.json)</button>
        <input type="file" id="au-imp-file" accept=".json" hidden>
      </div>
      ${!isReg&&users.length>1?`<div style="margin-top:16px;padding-top:12px;border-top:1px solid var(--line)"><small style="color:var(--mut);display:block;margin-bottom:6px">Account salvati su questo browser:</small><div class="row">${users.map(u=>`<button type="button" class="ch" data-quicku="${e(u.username)}">${e(u.username)}</button>`).join("")}</div></div>`:""}
    </div>`;
    gate.classList.add("show");
    $("#au-imp-prof").onclick=()=>$("#au-imp-file").click();
    $("#au-imp-file").onchange=async ev=>{
      const f=ev.target.files[0];if(!f)return;
      try{
        const obj=JSON.parse(await f.text());
        if(obj.app!=="meganavigatore_profile"||!obj.account||!obj.account.username)throw"Il file selezionato non è un profilo completo valido.";
        const users=AUTH.getUsers();
        const k=obj.account.username.toLowerCase();
        users[k]=obj.account;
        AUTH.saveUsers(users);
        AUTH.cur=obj.account.username;
        AUTH.setSession(AUTH.cur,true);
        if(obj.impostazioni)setCfg(obj.impostazioni);
        if(obj.chiavi_api){
          if(obj.chiavi_api.tmdb)localStorage.setItem("mn_tmdb",obj.chiavi_api.tmdb);
          if(obj.chiavi_api.rb)localStorage.setItem("mn_rb",obj.chiavi_api.rb);
        }
        gate.classList.remove("show");
        await bootUserSession(false);
        const ok=okTables(obj.tabelle||{});
        if(Object.keys(ok).length)await replaceAll(ok);
        render();
        toast("Profilo di "+AUTH.cur+" importato con successo!");
      }catch(err){$("#au-err").textContent=String(err)}
    };
    $("#tab-login").onclick=()=>showAuthGate("login");
    $("#tab-reg").onclick=()=>showAuthGate("register");
    gate.querySelectorAll("[data-quicku]").forEach(b=>b.onclick=()=>{$("#au-user").value=b.dataset.quicku;$("#au-pass").focus()});
    $("#auth-form").onsubmit=async ev=>{
      ev.preventDefault();
      const errEl=$("#au-err");errEl.textContent="";
      const u=$("#au-user").value,p=$("#au-pass").value;
      try{
        if(isReg){
          const p2=$("#au-pass2").value;
          if(p!==p2)throw"Le due password non coincidono.";
          const loadSeed=$("#au-seed").checked;
          await AUTH.register(u,p,loadSeed);
          gate.classList.remove("show");
          await bootUserSession(loadSeed);
          toast("Benvenuto, "+AUTH.cur+"!");
        }else{
          const rem=$("#au-rem").checked;
          await AUTH.login(u,p,rem);
          gate.classList.remove("show");
          await bootUserSession(false);
          toast("Bentornato, "+AUTH.cur+"!");
        }
      }catch(msg){errEl.textContent=String(msg)}
    };
    setTimeout(()=>$("#au-user").focus(),50);
  }

