  function checkWlAutocomplete(ta){
    const pos=ta.selectionStart;
    const before=ta.value.slice(0,pos);
    const openIdx=before.lastIndexOf("[[");
    if(openIdx===-1){closeWlAc();return}
    const between=before.slice(openIdx+2);
    if(between.includes("]]")||between.includes("\n")){closeWlAc();return}
    WL_AC_RANGE={start:openIdx,end:pos};
    WL_AC_ITEMS=buildWlCandidates(between);
    WL_AC_IDX=0;
    renderWlAc(ta);
  }
