  $("#fi").addEventListener("change",ev=>{if(ev.target.files[0])imp(ev.target.files[0]);ev.target.value=""});

  $("#main").addEventListener("dragstart",ev=>{const c=ev.target.closest("[data-tid]");if(c)ev.dataTransfer.setData("text/plain",c.dataset.tid)});
  $("#main").addEventListener("dragover",ev=>{const col=ev.target.closest("[data-col]");if(col){ev.preventDefault();col.classList.add("drop-over")}});
  $("#main").addEventListener("dragleave",ev=>{const col=ev.target.closest("[data-col]");if(col)col.classList.remove("drop-over")});
  $("#main").addEventListener("drop",async ev=>{const c=ev.target.closest("[data-col]");if(!c)return;ev.preventDefault();c.classList.remove("drop-over");const p=curP(),a=p&&p.attivita.find(x=>x.id==ev.dataTransfer.getData("text/plain"));if(a&&a.stato!=c.dataset.col){a.stato=c.dataset.col;await savP(p);render()}});
  let touchDrag=null;
  $("#main").addEventListener("touchstart",ev=>{const tk=ev.target.closest(".tk");if(!tk||ev.target.closest("button"))return;const t=ev.touches[0];touchDrag={el:tk,tid:tk.dataset.tid,sx:t.clientX,sy:t.clientY,active:false}},{passive:true});
  $("#main").addEventListener("touchmove",ev=>{if(!touchDrag)return;const t=ev.touches[0],dx=t.clientX-touchDrag.sx,dy=t.clientY-touchDrag.sy;
  if(!touchDrag.active&&Math.hypot(dx,dy)>10){touchDrag.active=true;touchDrag.el.classList.add("dragging")}
  if(touchDrag.active){ev.preventDefault();document.querySelectorAll(".col.drop-over").forEach(c=>c.classList.remove("drop-over"));const under=document.elementFromPoint(t.clientX,t.clientY);const col=under&&under.closest("[data-col]");if(col)col.classList.add("drop-over")}},{passive:false});
  $("#main").addEventListener("touchend",async ev=>{if(!touchDrag)return;const td=touchDrag;touchDrag=null;td.el.classList.remove("dragging");document.querySelectorAll(".col.drop-over").forEach(c=>c.classList.remove("drop-over"));
  if(!td.active)return;const t=ev.changedTouches[0],under=document.elementFromPoint(t.clientX,t.clientY),col=under&&under.closest("[data-col]");
  if(col){const p=curP(),a=p&&p.attivita.find(x=>x.id==td.tid);if(a&&a.stato!=col.dataset.col){a.stato=col.dataset.col;await savP(p);render()}}});
  async function init(){
    const NAVIC={home:"DB",serie_tv:"TV",film:"FM",animazione:"AN",lego:"LG",libri:"LB",saghe:"SG",statistiche:"ST",incorso:"CA",controlla:"CK",progetti:"PJ",codice:"CD",account:"AC"};const navBtn=([k,l])=>{const tx=String(l).trim(),ic=NAVIC[k]||tx.slice(0,2).toUpperCase();return `<button data-go="${k}" data-label="${tx}" title="${tx}"><span class="ni">${ic}</span><span class="nl">${tx}</span></button>`};
    $("#nav").innerHTML=[
      navBtn(["home","Dashboard"]),
      '<div class="nav-sep"></div>',
      ...names.map(n=>navBtn([n,T[n].i+" "+T[n].n])),
      '<div class="nav-sep"></div>',
      navBtn(["incorso","Calendario & In corso"]),
      '<div class="nav-sep"></div>',
      ...[["saghe","Saghe"],["statistiche","Statistiche"],["ai","AI locale"],["trofei","Trofei"],["controlla","Controlla"],["progetti","Progetti"],["codice","Codice"],["architettura","Sistema & backup"]].map(x=>navBtn(x)),
      '<div class="nav-sep"></div>',
      navBtn(["account","Account"])
    ].join("");
    sideApply();sideHeight();
    $("#scrim").onclick=()=>document.body.classList.remove("so");
    $("#pls").innerHTML=Object.keys(PLT).map(p=>`<option value="${p}">`).join("");
    $("#usr-btn").onclick=()=>go("account");
    initPWA();
    const savedUser=AUTH.getSession();
    const users=AUTH.getUsers();
    if(savedUser&&users[savedUser.toLowerCase()]){
      AUTH.cur=users[savedUser.toLowerCase()].username;
      await bootUserSession(false);
    }else{
      showAuthGate(Object.keys(users).length?"login":"register");
    }
  }
  init();
  
